// /download: a tiny Worker that runs first for this one path only (wrangler.jsonc
// assets.run_worker_first). It 302-redirects to the newest release's .apk (the universal build when
// there are several), whatever the asset is called, so the site never links to an APK file name.
// Every other path is served by the static assets binding.
//
// vars (generated by scripts/sync-config.mjs from site.config.json):
//   GITHUB_REPO  "owner/name"
//   USER_AGENT   sent to the GitHub API, which rejects requests without one

const CACHE_TTL = 600; // seconds: the GitHub API answer is reused for 10 minutes

export const releasesUrl = (repo) => `https://github.com/${repo}/releases/latest`;
export const apiUrl = (repo) => `https://api.github.com/repos/${repo}/releases/latest`;

// ABI-split builds (one APK per CPU architecture) are named after the ABI.
const ABI = /(arm64|armeabi|aarch64|x86|mips)/i;

/**
 * The APK to send: a universal build first, then any APK not tied to one CPU architecture, then the
 * first APK. Releases that ever ship split APKs therefore still get the build that installs everywhere.
 */
export function pickApk(assets) {
  const apks = (assets || []).filter(
    (a) => typeof a?.name === 'string' && a.name.toLowerCase().endsWith('.apk') && a.browser_download_url,
  );
  return apks.find((a) => /universal/i.test(a.name)) || apks.find((a) => !ABI.test(a.name)) || apks[0] || null;
}

function redirect(location) {
  return new Response(null, {
    status: 302,
    headers: {
      Location: location,
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'strict-origin-when-cross-origin',
    },
  });
}

/** The latest release JSON, from the Cache API when fresh, otherwise from GitHub (then cached). */
async function latestRelease(repo, userAgent, ctx) {
  const url = apiUrl(repo);
  const key = new Request(url, { method: 'GET' });
  const cache = globalThis.caches?.default;

  if (cache) {
    const hit = await cache.match(key);
    if (hit) return hit.json();
  }

  const res = await fetch(url, {
    // a renamed repository answers with a 301 to its new home: follow it (the Workers default, made explicit)
    redirect: 'follow',
    headers: {
      'User-Agent': userAgent,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
    },
  });
  if (!res.ok) throw new Error(`GitHub API ${res.status}`);
  const body = await res.text();
  const data = JSON.parse(body);

  if (cache) {
    const stored = new Response(body, {
      headers: { 'Content-Type': 'application/json', 'Cache-Control': `public, max-age=${CACHE_TTL}` },
    });
    const put = cache.put(key, stored);
    if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(put);
    else await put;
  }
  return data;
}

export default {
  async fetch(request, env, ctx) {
    const { pathname } = new URL(request.url);
    // '/download/' (a trailing-slash habit, a link shortener) means the same thing
    if (pathname.replace(/\/+$/, '') !== '/download') return env.ASSETS.fetch(request);

    const repo = env.GITHUB_REPO || 'Sriharan-S/gps-mock';
    const fallback = releasesUrl(repo);
    try {
      const release = await latestRelease(repo, env.USER_AGENT || 'site-download-worker', ctx);
      const apk = pickApk(release?.assets);
      return redirect(apk ? apk.browser_download_url : fallback);
    } catch {
      return redirect(fallback);
    }
  },
};
